files.content:
body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  min-block-size: 100dvh;
}

.wrapper {
  max-inline-size: 850px;
}

p {
  margin: 40px;
  color: #fff;
  font-weight: bold;
  font-size: 6em;
}

.stroke {
  color: transparent;
}

.stroke {
  color: transparent;
  text-shadow: 7px 5px #d3deed;
}

@supports (-webkit-text-stroke: 2px #000) {
  .stroke {
    -webkit-text-stroke: 2px #000;
    animation: fill 1.5s infinite;
  }
}

@keyframes fill {
  from { -webkit-text-stroke: 2px #00008b; }
  to { -webkit-text-stroke: 6px #e0b3ff; }
}
@media (prefers-reduced-motion: reduce) { .stroke { animation: none; } }
